  "starter": "import sys\n\nfrom crossword import *\n\n\nclass CrosswordCreator():\n\n    def __init__(self, crossword):\n        \"\"\"\n        Create new CSP crossword generate.\n        \"\"\"\n        self.crossword = crossword\n        self.domains = {\n            var: self.crossword.words.copy()\n            for var in self.crossword.variables\n        }\n\n    def letter_grid(self, assignment):\n        \"\"\"\n        Return 2D array representing a given assignment.\n        \"\"\"\n        letters = [\n            [None for _ in range(self.crossword.width)]\n            for _ in range(self.crossword.height)\n        ]\n        for variable, word in assignment.items():\n            direction = variable.direction\n            for k in range(len(word)):\n                i = variable.i + (k if direction == Variable.DOWN else 0)\n                j = variable.j + (k if direction == Variable.ACROSS else 0)\n                letters[i][j] = word[k]\n        return letters\n\n    def print(self, assignment):\n        \"\"\"\n        Print crossword assignment to the terminal.\n        \"\"\"\n        letters = self.letter_grid(assignment)\n        for i in range(self.crossword.height):\n            for j in range(self.crossword.width):\n                if self.crossword.structure[i][j]:\n                    print(letters[i][j] or \" \", end=\"\")\n                else:\n                    print(\"█\", end=\"\")\n            print()\n\n    def save(self, assignment, filename):\n        \"\"\"Суретке сақтау (Pillow қажет; браузерде керек емес).\"\"\"\n        raise NotImplementedError\n\n    def solve(self):\n        \"\"\"\n        Enforce node and arc consistency, and then solve the CSP.\n        \"\"\"\n        self.enforce_node_consistency()\n        self.ac3()\n        return self.backtrack(dict())\n\n    def enforce_node_consistency(self):\n        \"\"\"\n        Update `self.domains` such that each variable is node-consistent.\n        (Remove any values that are inconsistent with a variable's unary\n         constraints; in this case, the length of the word.)\n        \"\"\"\n        # TODO: әр айнымалының доменінен ұзындығы сәйкес келмейтін сөздерді алып тастаңыз\n        raise NotImplementedError\n\n    def revise(self, x, y):\n        \"\"\"\n        Make variable `x` arc consistent with variable `y`.\n        To do so, remove values from `self.domains[x]` for which there is no\n        possible corresponding value for `y` in `self.domains[y]`.\n\n        Return True if a revision was made to the domain of `x`; return\n        False if no revision was made.\n        \"\"\"\n        # TODO: self.crossword.overlaps[x, y] арқылы қиылысуды алыңыз (None болуы мүмкін)\n        raise NotImplementedError\n\n    def ac3(self, arcs=None):\n        \"\"\"\n        Update `self.domains` such that each variable is arc consistent.\n        If `arcs` is None, begin with initial list of all arcs in the problem.\n        Otherwise, use `arcs` as the initial list of arcs to make consistent.\n\n        Return True if arc consistency is enforced and no domains are empty;\n        return False if one or more domains end up empty.\n        \"\"\"\n        # TODO: кезек құрыңыз, revise шақырыңыз, домен өзгерсе көршілерді кезекке қосыңыз\n        raise NotImplementedError\n\n    def assignment_complete(self, assignment):\n        \"\"\"\n        Return True if `assignment` is complete (i.e., assigns a value to each\n        crossword variable); return False otherwise.\n        \"\"\"\n        # TODO\n        raise NotImplementedError\n\n    def consistent(self, assignment):\n        \"\"\"\n        Return True if `assignment` is consistent (i.e., words fit in crossword\n        puzzle without conflicting characters); return False otherwise.\n        \"\"\"\n        # TODO: сөздер әртүрлі ме, ұзындығы дұрыс па, көршілермен қиылысу сәйкес пе\n        raise NotImplementedError\n\n    def order_domain_values(self, var, assignment):\n        \"\"\"\n        Return a list of values in the domain of `var`, in order by\n        the number of values they rule out for neighboring variables.\n        The first value in the list, for example, should be the one\n        that rules out the fewest values among the neighbors of `var`.\n        \"\"\"\n        # TODO: алдымен кез келген ретпен қайтарсаңыз да болады, кейін эвристиканы қосыңыз\n        raise NotImplementedError\n\n    def select_unassigned_variable(self, assignment):\n        \"\"\"\n        Return an unassigned variable not already part of `assignment`.\n        Choose the variable with the minimum number of remaining values\n        in its domain. If there is a tie, choose the variable with the highest\n        degree. If there is a tie, any of the tied variables are acceptable\n        return values.\n        \"\"\"\n        # TODO\n        raise NotImplementedError\n\n    def backtrack(self, assignment):\n        \"\"\"\n        Using Backtracking Search, take as input a partial assignment for the\n        crossword and return a complete assignment if possible to do so.\n\n        `assignment` is a mapping from variables (keys) to words (values).\n\n        If no assignment is possible, return None.\n        \"\"\"\n        # TODO\n        raise NotImplementedError\n\n\ndef main():\n\n    # Check usage\n    if len(sys.argv) not in [3, 4]:\n        sys.exit(\"Usage: python generate.py structure words [output]\")\n\n    # Parse command-line arguments\n    structure = sys.argv[1]\n    words = sys.argv[2]\n    output = sys.argv[3] if len(sys.argv) == 4 else None\n\n    # Generate crossword\n    crossword = Crossword(structure, words)\n    creator = CrosswordCreator(crossword)\n    assignment = creator.solve()\n\n    # Print result\n    if assignment is None:\n        print(\"No solution.\")\n    else:\n        creator.print(assignment)\n        if output:\n            creator.save(assignment, output)\n\n\nif __name__ == \"__main__\" and len(sys.argv) > 1:\n    main()\n",
